// Outer loop - 40.0 iterations
for(int iter = 0; iter < 40; iter++) {
i += 1.0;
// Update z and calculate distance field
f = 0.003 + abs(length(p.xy) + dot(cos(p), sin(p / 0.6).yzx) - 5.0) / 7.0;
z += f;
// Add to output color (GRB channel swizzle: green, red, blue)
o.grb += (1.5 - p / z) / f;
// Update ray position
p = z * (FC.rgb * 2.0 - vec3(r.x, r.y, r.y)) / r.y;
p.z -= t;
// Inner loop - 6.0 iterations for fractal detail
for(int j = 1; j <= 6; j++) {
f = float(j);
p += sin(round(p * 6.0) / 6.0 * f - t * q3) / f;
}
}
// Apply final transformation
o = tanh(o / 3000.0);
// Output final color
ret = o.rgb;
}

